input.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2b3236;
  background: #ffffff;
}

a {
  color: inherit;
}

/* One content column for the whole page, centered on wide screens. */
.site-header,
.hero,
.features {
  max-width: 1200px;
  margin: 0 auto;
  padding-left: 64px;
  padding-right: 64px;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 22px;
  padding-bottom: 22px;
}

.logo {
  font-size: 19px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: 28px;
}

.site-nav a {
  text-decoration: none;
  color: #4d585e;
}

/* Hero: the promise on the left, the product (today's tides) on the right. */
.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
  padding-top: 72px;
  padding-bottom: 72px;
}

.hero-text {
  max-width: 440px;
}

h1 {
  margin: 0 0 16px;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.25;
}

.hero-text p {
  margin: 0 0 24px;
  color: #4d585e;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #1f5f7a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

h2 {
  margin: 0 0 12px;
  font-size: 19px;
  font-weight: 500;
  line-height: 1.3;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 15px;
  color: #2b3236;
}

th,
td {
  padding: 10px 0;
  text-align: left;
  font-weight: 400;
  border-bottom: 1px solid #dfe3e5;
}

th {
  padding-top: 0;
  font-size: 13px;
  color: #4d585e;
}

/* Right-align numbers, with every digit the same width, so they line up in columns. */
.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.time {
  font-size: 19px;
  font-weight: 500;
}

/* The three features, in a row under a thin rule. */
.features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  padding-bottom: 72px;
}

.point {
  padding-top: 24px;
  border-top: 1px solid #dfe3e5;
}

.point h3 {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 500;
}

.point p {
  margin: 0;
  max-width: 36em;
  color: #4d585e;
}

/* Tablet: stack the features so each line keeps a readable length. */
@media (max-width: 900px) {
  .features {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .point {
    padding-bottom: 24px;
  }
}

/* Phone: one column, the navigation on its own row under the logo. */
@media (max-width: 720px) {
  .site-header,
  .hero,
  .features {
    padding-left: 24px;
    padding-right: 24px;
  }

  .site-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .site-nav {
    gap: 20px;
  }

  .hero {
    grid-template-columns: 1fr;
    gap: 48px;
    padding-top: 40px;
    padding-bottom: 48px;
  }
}

